export interface Receipt { id: number; tenant: string; key: string; cents: number }
interface Entry { cents: number; receipt: Receipt }
export class Ledger {
  readonly entries: Receipt[] = [];
  // tenant -> key -> original debit. Nested maps avoid delimiter collisions.
  private readonly debits = new Map<string, Map<string, Entry>>();
  async apply(tenant: string, key: string, cents: number): Promise<Receipt> {
    // No await before this point: lookup and insert happen in one synchronous step,
    // so concurrent calls with the same tenant/key cannot both debit.
    let keys = this.debits.get(tenant);
    if (!keys) { keys = new Map(); this.debits.set(tenant, keys); }
    const existing = keys.get(key);
    if (existing) {
      if (existing.cents !== cents) throw new Error('key conflict');
      return existing.receipt;
    }
    const receipt: Receipt = { id: this.entries.length + 1, tenant, key, cents };
    this.entries.push(receipt);
    keys.set(key, { cents, receipt });
    return receipt;
  }
}

